<?php

// CAT-019 extraído del catálogo oficial compartido para Facturación Electrónica.
// Se conserva comprimido para mantener el repositorio liviano y se expande al ejecutar la migración.
$payload = '';

$json = gzdecode(base64_decode($payload, true));
if ($json === false) {
    throw new RuntimeException('No fue posible expandir CAT-019.');
}

return json_decode($json, true, 512, JSON_THROW_ON_ERROR);
